// ig5_package action=firmware / unpack through the public tool definition and the real bundled-Python worker.
// Needs the bundled Python (extended tier). The image is generated by scripts/fixtures/make_firmware_sample.py and only read.
import assert from 'node:assert/strict';
import { AsyncLocalStorage } from 'node:async_hooks';
import { spawnSync } from 'node:child_process';
import { createHash } from 'node:crypto';
import fs from 'node:fs';
import os from 'node:os';
import path from 'node:path';
import test from 'node:test';
import { fileURLToPath } from 'node:url';
import { createAnalysisService, defineAnalysisTools } from '../analysis_tools.js';

const root = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');
const python = process.env.IG5_PYTHON || path.join(root, 'runtimes', 'ghidra', 'python', 'python.exe');
assert(fs.existsSync(python), `bundled Python not found: ${python} (set IG5_PYTHON)`);
const scratch = fs.mkdtempSync(path.join(fs.realpathSync(os.tmpdir()), 'ig5-fw-tool-'));
const image = path.join(scratch, 'nested firmware.bin');
const made = spawnSync(python, ['-I', '-B', path.join(root, 'scripts', 'fixtures', 'make_firmware_sample.py'), image], { encoding: 'utf8' });
assert.equal(made.status, 0, made.stderr);
const cfg = { artifactDir: path.join(scratch, 'artifacts'), defaultEngine: 'ghidra', ghidra: { pythonExe: python } };
const mgr = { scope: new AsyncLocalStorage(), checkCancelled() { if (mgr.scope.getStore()?.signal?.aborted) throw Object.assign(new Error('Cancelled'), { code: 'ABORT_ERR' }); } };
const service = createAnalysisService(mgr, cfg); mgr.analysis = service;
const tool = new Map(defineAnalysisTools(mgr, cfg, value => value).map(t => [t.name, t])).get('ig5_package');
const call = args => tool.execute(args);
const rejects = (run, code) => assert.rejects(run, error => error.code === code, `expected ${code}`);
test.after(async () => { await service.dispose(); fs.rmSync(scratch, { recursive: true, force: true }); });
const sha = file => createHash('sha256').update(fs.readFileSync(file)).digest('hex');

let scanned;
test('firmware scan returns a bounded brief and saves the full inventory', async () => {
  const before = sha(image);
  scanned = await call({ action: 'firmware', input: { path: image } });
  assert.equal(scanned.kind, 'firmware'); assert.equal(scanned.input.sha256, before); assert.equal(sha(image), before, 'the image is untouched');
  const view = scanned.value;
  assert.equal(view.schema, 'ig5.firmware.v1'); assert.deepEqual(view.outline.map(o => o.format), ['uimage', 'gzip', 'xz', 'squashfs', 'cpio']);
  assert.equal(view.summary.busyboxVersion, '1.31.1'); assert.match(view.summary.kernelBanner, /^Linux version 4\.14\.180/); assert.deepEqual({ ...view.summary.executableArchitectures }, { 'ARM 32-bit': 1 });
  assert.equal(view.extraction, undefined); assert.ok(Buffer.byteLength(JSON.stringify(scanned)) < 30000);
});

test('sections of the saved inventory are readable, and APK reports are a different lane', async () => {
  const fsInfo = await call({ action: 'result', result_id: scanned.result_id, select: 'components.1.children.0.components.0.filesystem.files' });
  assert.equal(fsInfo.value, 3);
  const listing = await call({ action: 'result', result_id: scanned.result_id, select: 'summary.interesting' });
  assert.deepEqual(listing.value.credentialsFile ?? listing.value['credentials-file'], ['etc/passwd']);
  await rejects(() => call({ action: 'result', result_id: scanned.result_id, select: '__proto__' }), 'INVALID_INPUT');
  await rejects(() => call({ action: 'result', result_id: '00000000-0000-0000-0000-000000000000' }), 'NOT_FOUND');
});

test('unpack extracts under a fresh root inside the artifact directory and nowhere else', async () => {
  const outside = path.join(scratch, 'outside.txt'), parentOutside = path.join(path.dirname(scratch), 'outside.txt');
  const before = fs.readdirSync(scratch).sort();
  const result = await call({ action: 'unpack', input: { path: image } });
  assert.equal(result.action, 'unpack');
  const extraction = result.value.extraction;
  assert.ok(extraction.root.startsWith(path.join(cfg.artifactDir, 'firmware') + path.sep)); assert.ok(extraction.files >= 5);
  const items = (await call({ action: 'result', result_id: result.result_id, select: 'extraction.items' })).value;
  assert.ok(items.some(i => i.archivePath === 'etc/passwd' && fs.readFileSync(path.join(extraction.root, i.path), 'utf8').startsWith('root:x:0:0')));
  assert.ok(items.every(i => path.resolve(extraction.root, i.path).startsWith(extraction.root + path.sep)));
  assert.equal(fs.existsSync(outside), false); assert.equal(fs.existsSync(parentOutside), false, 'a ../../ name did not escape');
  assert.deepEqual(fs.readdirSync(scratch).sort(), [...before, 'artifacts'].filter((v, i, a) => a.indexOf(v) === i).sort());
  const second = await call({ action: 'unpack', input: { path: image } });
  assert.notEqual(second.value.extraction.root, extraction.root, 'every unpack gets its own directory');
});

test('only an explicit file path is accepted; problems come back as codes', async () => {
  for (const input of [undefined, null, {}, { path: 5 }, { path: image, extra: 1 }, { encoding: 'hex', data: '00' }]) await rejects(() => call({ action: 'firmware', input }), 'INVALID_INPUT');
  await rejects(() => call({ action: 'firmware', input: { path: image }, select: 'x' }), 'INVALID_INPUT');
  await rejects(() => call({ action: 'explode', input: { path: image } }), 'INVALID_INPUT');
  await rejects(() => call({ action: 'firmware', input: { path: path.join(scratch, 'missing.bin') } }), 'INPUT');
  await rejects(() => call({ action: 'firmware', input: { path: scratch } }), 'INPUT');
  const empty = path.join(scratch, 'empty.bin'); fs.writeFileSync(empty, '');
  await rejects(() => call({ action: 'firmware', input: { path: empty } }), 'INPUT');
});

test('a file with nothing recognisable is an empty inventory, not an error', async () => {
  const noise = path.join(scratch, 'noise.bin'); fs.writeFileSync(noise, Buffer.from(Array.from({ length: 50000 }, (_, i) => (i * 2654435761) >>> 24 & 0xff)));
  const result = await call({ action: 'firmware', input: { path: noise } });
  assert.deepEqual(result.value.outline, []); assert.deepEqual({ ...result.value.summary.formats }, {});
});

test('cancelling stops the worker and the service accepts the next request', async () => {
  const controller = new AbortController();
  const pending = mgr.scope.run({ signal: controller.signal }, () => call({ action: 'firmware', input: { path: image } }));
  controller.abort();
  await rejects(() => pending, 'ABORT_ERR');
  const again = await call({ action: 'firmware', input: { path: image } });
  assert.equal(again.kind, 'firmware');
});

test('without the bundled Python the failure is explicit', async () => {
  const bare = createAnalysisService({ ...mgr, analysis: undefined }, { artifactDir: path.join(scratch, 'bare'), defaultEngine: 'ghidra' });
  try { await rejects(() => bare.execute('package', { action: 'firmware', input: { path: image } }), 'NO_RUNTIME'); } finally { await bare.dispose(); }
});
